10	// allRect 覆盖整个（有限）平面，便于取全部当前有效路标。
11	func allRect() Rect { return Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9} }
12	
13	func activeLandmarks(t *testing.T, m *Map) map[string]Landmark {
14		t.Helper()
15		lms, err := m.LandmarksInRect(allRect())
16		if err != nil {
17			t.Fatal(err)
18		}
19		out := make(map[string]Landmark, len(lms))
20		for _, lm := range lms {
21			out[lm.ID] = lm
22		}
23		return out
24	}
