26	// 构造：t=100/200 两帧各观测 L（本地 (1,0)）与一帧 M；初始位姿 (0,0)。
27	func seedOccurrenceMap(t *testing.T) *Map {
28		t.Helper()
29		cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
30		m := newMap(t, cfg)
31		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
32			{Time: 100, Observations: []Observation{{ID: "L", X: 1, Y: 0}, {ID: "M", X: 2, Y: 0}}},
33			{Time: 200, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
34		}}); err != nil {
35			t.Fatal(err)
36		}
37		return m
38	}
