40	func TestInvalidateSuccessAndHistory(t *testing.T) {
41		m := seedOccurrenceMap(t)
42	
43		res, err := m.Invalidate(Invalidation{ID: "op1", Reason: "sign removed", Landmarks: []string{"L", "M"}})
44		if err != nil {
45			t.Fatalf("Invalidate: %v", err)
46		}
47		// 失效时间为提交时当前位姿时间。
48		if res.Time != 200 {
49			t.Fatalf("invalidate time = %d, want 200", res.Time)
50		}
51		// 结果按标识排序，编号为 1。
52		if len(res.Landmarks) != 2 ||
53			res.Landmarks[0] != (InvalidatedLandmark{ID: "L", Occurrence: 1}) ||
54			res.Landmarks[1] != (InvalidatedLandmark{ID: "M", Occurrence: 1}) {
55			t.Fatalf("invalidate result = %+v", res.Landmarks)
56		}
57	
58		// 区域查询立即排除，位姿与观测不删除。
59		if lms, _ := m.LandmarksInRect(allRect()); len(lms) != 0 {
60			t.Fatalf("invalidated landmarks still queried: %v", lms)
61		}
62		cur, _ := m.CurrentPose()
63		if cur.Time != 200 {
64			t.Fatalf("pose changed: %+v", cur)
65		}
66	
67		h, err := m.LandmarkAppearances("L")
68		if err != nil {
69			t.Fatal(err)
70		}
71		if h.ID != "L" || len(h.Appearances) != 1 {
72			t.Fatalf("history = %+v", h)
73		}
74		a := h.Appearances[0]
75		if a.Number != 1 || !a.HasFirstSeen || a.FirstSeenTime != 100 || a.Active {
76			t.Fatalf("appearance = %+v", a)
77		}
78		if a.Landmark.Count != 2 || a.Landmark.X != 1 || a.Landmark.Y != 0 {
79			t.Fatalf("appearance landmark = %+v", a.Landmark)
80		}
81		if a.InvalidTime != 200 || a.InvalidReason != "sign removed" || a.InvalidOpID != "op1" {
82			t.Fatalf("invalid info = %d %q %q", a.InvalidTime, a.InvalidReason, a.InvalidOpID)
83		}
84	
85		// 未知标识返回可区分的未找到结果。
86		if _, err := m.LandmarkAppearances("nope"); !errors.Is(err, ErrLandmarkNotFound) {
87			t.Fatalf("unknown id: %v", err)
88		}
89	}
