91	func TestInvalidateRejections(t *testing.T) {
92		m := seedOccurrenceMap(t)
93		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
94			t.Fatal(err)
95		}
96	
97		type tc struct {
98			name string
99			req  Invalidation
100			kind string
101			lm   string
102		}
103		cases := []tc{
104			{"empty id", Invalidation{Reason: "x", Landmarks: []string{"M"}}, RejectEmptyID, ""},
105			{"empty reason", Invalidation{ID: "x", Landmarks: []string{"M"}}, RejectEmptyReason, ""},
106			{"empty list", Invalidation{ID: "x", Reason: "r"}, RejectEmptyLandmarkList, ""},
107			{"empty landmark id", Invalidation{ID: "x", Reason: "r", Landmarks: []string{""}}, RejectEmptyID, ""},
108			{"duplicate entry", Invalidation{ID: "x", Reason: "r", Landmarks: []string{"M", "M"}}, RejectDuplicateLandmarkEntry, "M"},
109			{"unknown landmark", Invalidation{ID: "x", Reason: "r", Landmarks: []string{"ZZ"}}, RejectLandmarkNotFound, "ZZ"},
110			{"already invalidated", Invalidation{ID: "x", Reason: "r", Landmarks: []string{"L"}}, RejectLandmarkInactive, "L"},
111		}
112		for _, c := range cases {
113			t.Run(c.name, func(t *testing.T) {
114				_, err := m.Invalidate(c.req)
115				r, ok := AsRejectError(err)
116				if !ok || r.Kind != c.kind {
117					t.Fatalf("err = %v, want %s", err, c.kind)
118				}
119				if c.lm != "" && (!r.HasLandmark || r.Landmark != c.lm) {
120					t.Fatalf("landmark = %q, want %q", r.Landmark, c.lm)
121				}
122			})
123		}
124	
125		// 一次操作中单个路标不合法，整次拒绝：M 仍有效（未被连带撤下）。
126		_, err := m.Invalidate(Invalidation{ID: "batch", Reason: "r", Landmarks: []string{"M", "L"}})
127		r, ok := AsRejectError(err)
128		if !ok || r.Kind != RejectLandmarkInactive || r.Landmark != "L" {
129			t.Fatalf("batch err = %v", err)
130		}
131		if _, err := m.LandmarkAppearances("M"); err != nil {
132			t.Fatal(err)
133		}
134		if hm, _ := m.LandmarkAppearances("M"); !hm.Appearances[0].Active {
135			t.Fatal("M was partially invalidated")
136		}
137	}
