139	func TestReappearanceNumberingAndMerge(t *testing.T) {
140		m := seedOccurrenceMap(t)
141		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
142			t.Fatal(err)
143		}
144	
145		// 新轨迹在远处重新看到 L：旧记录不参与合并，距离再远也不冲突。
146		// t=300 位姿 (10,0)，本地 (0,0) → 地图 (10,0)；同帧第二次观测
147		// (0,0.5) 在合并距离内，编号 2、计数从 1 起递增。
148		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
149			{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}, {ID: "L", X: 0, Y: 0.5}}},
150		}}); err != nil {
151			t.Fatalf("reappearance: %v", err)
152		}
153		lms := activeLandmarks(t, m)
154		lm, ok := lms["L"]
155		if !ok {
156			t.Fatal("active L missing")
157		}
158		if lm.Count != 2 {
159			t.Fatalf("count = %d, want 2", lm.Count)
160		}
161		approxEq(t, "new y", lm.Y, 0.25)
162		approxEq(t, "new x", lm.X, 10)
163	
164		h, _ := m.LandmarkAppearances("L")
165		if len(h.Appearances) != 2 {
166			t.Fatalf("history len = %d", len(h.Appearances))
167		}
168		if h.Appearances[0].Active || h.Appearances[0].Number != 1 {
169			t.Fatalf("occ1 = %+v", h.Appearances[0])
170		}
171		a2 := h.Appearances[1]
172		if !a2.Active || a2.Number != 2 || !a2.HasFirstSeen || a2.FirstSeenTime != 300 {
173			t.Fatalf("occ2 = %+v", a2)
174		}
175	
176		// 再次失效撤下的是第 2 次出现。
177		res, err := m.Invalidate(Invalidation{ID: "op2", Reason: "gone again", Landmarks: []string{"L"}})
178		if err != nil {
179			t.Fatal(err)
180		}
181		if res.Time != 300 || res.Landmarks[0].Occurrence != 2 {
182			t.Fatalf("second invalidation = %+v", res)
183		}
184		h, _ = m.LandmarkAppearances("L")
185		for _, ap := range h.Appearances {
186			if ap.Active {
187				t.Fatalf("occurrence %d still active", ap.Number)
188			}
189		}
190	
191		// 第三次出现编号为 3。
192		if _, err := m.ImportSegment(Segment{ID: "s3", Frames: []Frame{
193			{Time: 400, DX: 0, Observations: []Observation{{ID: "L", X: -5, Y: 0}}},
194		}}); err != nil {
195			t.Fatal(err)
196		}
197		h, _ = m.LandmarkAppearances("L")
198		if len(h.Appearances) != 3 || !h.Appearances[2].Active || h.Appearances[2].Number != 3 {
199			t.Fatalf("occ3 = %+v", h.Appearances)
200		}
201		if c := h.Appearances[2].Landmark.Count; c != 1 {
202			t.Fatalf("occ3 count = %d, want 1", c)
203		}
204	}
