206	func TestReappearanceRejectedSegmentConsumesNothing(t *testing.T) {
207		m := seedOccurrenceMap(t)
208		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
209			t.Fatal(err)
