219		}
220		// 随后合法再现仍是编号 2。
221		if _, err := m.ImportSegment(Segment{ID: "good", Frames: []Frame{
222			{Time: 300, DX: 10, Observations: []Observation{{ID: "L"}}},
223		}}); err != nil {
224			t.Fatal(err)
225		}
226		h, _ = m.LandmarkAppearances("L")
