280	func TestDuplicateImportDoesNotReactivate(t *testing.T) {
281		m := seedOccurrenceMap(t)
282		orig := Segment{ID: "s1", Frames: []Frame{
283			{Time: 100, Observations: []Observation{{ID: "L", X: 1, Y: 0}, {ID: "M", X: 2, Y: 0}}},
284			{Time: 200, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
