286		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
287			t.Fatal(err)
288		}
289		// 原轨迹重复导入：返回首次结果，occ1 不复活、观测不增加。
290		res, err := m.ImportSegment(orig)
291		if err != nil {
292			t.Fatal(err)
293		}
294		if res.EndPose.Time != 200 {
295			t.Fatalf("duplicate result = %+v", res.EndPose)
296		}
297		h, _ := m.LandmarkAppearances("L")
298		if len(h.Appearances) != 1 || h.Appearances[0].Active || h.Appearances[0].Landmark.Count != 2 {
299			t.Fatalf("occ1 changed on duplicate import: %+v", h.Appearances)
300		}
301	}
