303	func TestInvalidatePersistRoundTrip(t *testing.T) {
304		path := filepath.Join(t.TempDir(), "map.pose")
305		m, err := Create(path, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0})
306		if err != nil {
307			t.Fatal(err)
308		}
309		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
310			{Time: 100, Observations: []Observation{{ID: "L", X: 1}}},
311		}}); err != nil {
312			t.Fatal(err)
313		}
314		first, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}})
315		if err != nil {
316			t.Fatal(err)
317		}
318		if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
319			{Time: 200, DX: 5, Observations: []Observation{{ID: "L"}}},
320		}}); err != nil {
321			t.Fatal(err)
322		}
323		if err := m.Close(); err != nil {
324			t.Fatal(err)
325		}
326	
327		m2, err := Open(path)
328		if err != nil {
329			t.Fatal(err)
330		}
331		defer m2.Close()
332	
333		h, err := m2.LandmarkAppearances("L")
334		if err != nil {
335			t.Fatal(err)
336		}
337		if len(h.Appearances) != 2 {
338			t.Fatalf("history after reopen = %+v", h.Appearances)
339		}
340		if h.Appearances[0].Active || h.Appearances[0].InvalidReason != "gone" ||
341			h.Appearances[0].InvalidTime != 100 || h.Appearances[0].InvalidOpID != "op1" {
342			t.Fatalf("occ1 after reopen = %+v", h.Appearances[0])
343		}
344		if !h.Appearances[1].Active || h.Appearances[1].Number != 2 ||
345			h.Appearances[1].FirstSeenTime != 200 || h.Appearances[1].Landmark.Count != 1 {
346			t.Fatalf("occ2 after reopen = %+v", h.Appearances[1])
347		}
348		lms, _ := m2.LandmarksInRect(allRect())
349		if len(lms) != 1 || lms[0].X != 5 || lms[0].Count != 1 {
350			t.Fatalf("active after reopen = %v", lms)
351		}
352	
353		// 失效重复提交与冲突提交在重开后一致。
354		again, err := m2.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}})
355		if err != nil || again.Time != first.Time || again.Landmarks[0].Occurrence != 1 {
356			t.Fatalf("duplicate invalidation after reopen: %v %+v", err, again)
357		}
358		h, _ = m2.LandmarkAppearances("L")
359		if !h.Appearances[1].Active {
360			t.Fatal("duplicate op re-invalidated occ2 after reopen")
361		}
362		if _, err := m2.Invalidate(Invalidation{ID: "op1", Reason: "x", Landmarks: []string{"L"}}); err == nil {
363			t.Fatal("mismatch invalidation accepted after reopen")
364		}
365	}
