367	func TestInvalidateSaveFailureRollback(t *testing.T) {
368		dir := t.TempDir()
369		path := filepath.Join(dir, "map.pose")
370		m, err := Create(path, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0})
371		if err != nil {
372			t.Fatal(err)
373		}
374		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
375			{Time: 100, Observations: []Observation{{ID: "L", X: 1}}},
376		}}); err != nil {
377			t.Fatal(err)
378		}
379		if err := os.Remove(path); err != nil {
380			t.Fatal(err)
381		}
382		if err := os.Mkdir(path, 0o755); err != nil {
383			t.Fatal(err)
384		}
385		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err == nil {
386			t.Fatal("invalidate across directory target unexpectedly succeeded")
387		}
388		h, _ := m.LandmarkAppearances("L")
389		if len(h.Appearances) != 1 || !h.Appearances[0].Active {
390			t.Fatalf("state leaked after failed save: %+v", h.Appearances)
391		}
392		if lms, _ := m.LandmarksInRect(allRect()); len(lms) != 1 {
393			t.Fatalf("region query leaked: %v", lms)
394		}
395		// 恢复文件后同一操作标识仍可成功提交。
396		if err := os.Remove(path); err != nil {
397			t.Fatal(err)
398		}
399		if err := m.saveReplace(); err != nil {
400			t.Fatal(err)
401		}
402		if _, err := m.Invalidate(Invalidation{ID: "op1", Reason: "gone", Landmarks: []string{"L"}}); err != nil {
403			t.Fatalf("retry invalidation: %v", err)
404		}
405	}
