494		}
495		lc1, lc2 := rec.Landmarks[0], rec.Landmarks[1]
496		if lc1.ID != "L" || lc1.Occurrence != 1 ||
497			lc1.Before.X != 1 || lc1.After.X != 3 || lc1.Before.Count != 2 || lc1.After.Count != 2 {
498			t.Fatalf("occ1 change = %+v", lc1)
499		}
