507		if h.Appearances[0].Active || h.Appearances[0].InvalidReason != "gone" ||
508			h.Appearances[0].Landmark.Count != 2 || h.Appearances[0].Landmark.X != 3 {
509			t.Fatalf("occ1 after correction = %+v", h.Appearances[0])
510		}
511		if !h.Appearances[1].Active || h.Appearances[1].Landmark.X != 12 || h.Appearances[1].Landmark.Count != 1 {
512			t.Fatalf("occ2 after correction = %+v", h.Appearances[1])
513		}
514		lms := activeLandmarks(t, m)
515		if len(lms) != 1 || lms["L"].X != 12 {
516			t.Fatalf("active landmarks = %v", lms)
517		}
518	
519		// 第二次校正不改写既有记录，且新记录仍区分出现编号。
520		rec2, err := m.Correct(Correction{ID: "c2", Anchor: 300, Target: CorrectionTarget{X: 13, Y: 0}})
521		if err != nil {
522			t.Fatal(err)
523		}
