525			t.Fatalf("second record = %+v", rec2.Landmarks)
526		}
527		recs, _ := m.Corrections()
528		if len(recs) != 2 {
529			t.Fatalf("records = %d", len(recs))
530		}
531		if recs[0].Landmarks[0].After.X != 3 {
532			t.Fatalf("first record rewritten: %+v", recs[0].Landmarks[0])
