22	// 即使这些路标后来又再次出现也不会再次撤下它们；同一标识对应不同内容
23	// （原因或集合不同）则明确拒绝。
24	func (m *Map) Invalidate(req Invalidation) (InvalidationResult, error) {
25		m.mu.Lock()
26		defer m.mu.Unlock()
27		if m.closed {
28			return InvalidationResult{}, ErrClosed
29		}
30		st := m.state
31	
32		// 已保存的失效操作：相同内容直接返回首次结果；不同内容明确拒绝。
33		// 不做任何校验或状态变更，即使其后路标又再次出现。
34		setHash := landmarkSetHash(req.Landmarks)
35		if rec, ok := st.invalIndex[req.ID]; ok {
