package posemap

import "testing"

// 本文件为“校正记录的返回值是独立副本”这一已有行为提供回归保障：
// 调用方拿到 Correct 返回的记录或 Corrections 返回的列表后，无论
// 怎样改写其中的标识、目标、时间信息、位姿/路标前后值，或调换、
// 替换列表条目，都不能借此修改地图状态和已保存的校正历史。只使用
// 现有公开入口（ImportSegment/Correct/Corrections/Invalidate/
// LandmarkAppearances/CurrentPose/PoseAt/LandmarksInRect），不改变
// 任何公开使用方式与返回结果。

// snapshotRecord 在测试侧深拷贝一份记录作为期望快照。不复用被测
// 实现里的 cloneRecord，避免被测实现退化为浅拷贝时期望值与内部
// 状态共享底层切片、被一并改写而失去对照意义。
func snapshotRecord(rec CorrectionRecord) CorrectionRecord {
	cp := rec
	cp.Poses = append([]PoseChange(nil), rec.Poses...)
	cp.Landmarks = append([]LandmarkChange(nil), rec.Landmarks...)
	return cp
}

// scrambleRecord 模拟调用方就地改写一份校正记录的全部可写字段：
// 标识、锚点、目标、末帧时间，以及每条位姿/路标变化的出现编号与
// 校正前后值。若返回值不是独立副本，这些改写会污染地图内部状态。
func scrambleRecord(rec *CorrectionRecord) {
	rec.ID = "tampered"
	rec.Anchor = -999
	rec.Target = CorrectionTarget{X: -1, Y: -2, Heading: -3, Variance: -4}
	rec.EndTime = -1
	for i := range rec.Poses {
		rec.Poses[i].Before = Pose{Time: -1, X: -100, Y: -100, Heading: -100, Variance: -100}
		rec.Poses[i].After = Pose{Time: -2, X: -200, Y: -200, Heading: -200, Variance: -200}
	}
	for i := range rec.Landmarks {
		rec.Landmarks[i].ID = "tampered"
		rec.Landmarks[i].Occurrence = 999
		rec.Landmarks[i].Before = Landmark{ID: "tampered", X: -1, Y: -1, Count: -1}
		rec.Landmarks[i].After = Landmark{ID: "tampered", X: -2, Y: -2, Count: -2}
	}
}

// checkRecords 断言查询得到的记录列表与期望内容、次序完全一致。
func checkRecords(t *testing.T, got []CorrectionRecord, want ...CorrectionRecord) {
	t.Helper()
	if len(got) != len(want) {
		t.Fatalf("records len = %d, want %d: %v", len(got), len(want), got)
	}
	for i := range want {
		if !recordsEqual(got[i], want[i]) {
			t.Fatalf("record %d = %+v, want %+v", i, got[i], want[i])
		}
	}
}

func findLandmark(lms []Landmark, id string) (Landmark, bool) {
	for _, lm := range lms {
		if lm.ID == id {
			return lm, true
		}
	}
	return Landmark{}, false
}

// 成功校正同时包含多帧位姿变化与路标变化：改写返回记录后，再次查询
// 仍取得原始记录，当前位姿、历史位姿、路标位置与观测次数都保持成功
// 校正后的真实结果。
func TestCorrectionReturnedRecordIsolated(t *testing.T) {
	m := newMap(t, baseConfig())
	if _, err := m.ImportSegment(corrSegment()); err != nil {
		t.Fatal(err)
	}
	req := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
	rec, err := m.Correct(req)
	if err != nil {
		t.Fatalf("Correct: %v", err)
	}
	if len(rec.Poses) != 2 || len(rec.Landmarks) != 2 {
		t.Fatalf("record should cover 2 poses and 2 landmarks: %+v", rec)
	}
	want := snapshotRecord(rec)

	// 调用方改写标识、目标、时间信息以及位姿和路标的校正前后值。
	scrambleRecord(&rec)

	// 再次查询仍取得提交时的原始记录。
	recs, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, recs, want)

	// 当前位姿与相应时间的历史位姿保持真实校正结果。
	cur, _ := m.CurrentPose()
	if cur.Time != 200 || cur.X != 12 || cur.Y != 20 || cur.Variance != 2.25 {
		t.Fatalf("current = %+v, want corrected (12,20) v=2.25", cur)
	}
	p, _ := m.PoseAt(100)
	if p.Time != 100 || p.X != 10 || p.Y != 20 || p.Variance != 2 {
		t.Fatalf("pose at 100 = %+v, want corrected anchor", p)
	}
	p, _ = m.PoseAt(200)
	if p.Time != 200 || p.X != 12 || p.Y != 20 {
		t.Fatalf("pose at 200 = %+v, want corrected end pose", p)
	}

	// 路标位置与观测次数保持真实校正结果，不采用调用方改写的值。
	lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
	if len(lms) != 2 {
		t.Fatalf("landmarks = %v", lms)
	}
	l1, ok := findLandmark(lms, "L1")
	if !ok {
		t.Fatalf("L1 missing: %v", lms)
	}
	approxEq(t, "L1 x", l1.X, 11.5)
	approxEq(t, "L1 y", l1.Y, 20)
	if l1.Count != 2 {
		t.Fatalf("L1 count = %d, want 2", l1.Count)
	}
	mm, ok := findLandmark(lms, "M")
	if !ok {
		t.Fatalf("M missing: %v", lms)
	}
	approxEq(t, "M x", mm.X, 12)
	approxEq(t, "M y", mm.Y, 21)
	if mm.Count != 1 {
		t.Fatalf("M count = %d, want 1", mm.Count)
	}
}

// 校正跨越同一路标的两次出现（旧出现已失效、新出现仍有效）：改写
// 返回记录中的出现编号与各次前后值后，地图中两次出现的位置、计数
// 与失效信息都不受影响，区域查询仍只包含有效出现。
func TestCorrectionRecordIsolationAcrossOccurrences(t *testing.T) {
	m := newMap(t, baseConfig())
	// 全部沿世界 X 轴、朝向 0：初始位姿 (1,2)。
	// 第 1 次出现：t=100 观测 → (1,2)，t=200 观测 → (2,2)，均值 (1.5,2) 计数 2。
	if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
		{Time: 100, DX: 0, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
		{Time: 200, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
	}}); err != nil {
		t.Fatal(err)
	}
	inv, err := m.Invalidate(Invalidation{ID: "inv1", Reason: "stale", Landmarks: []string{"D"}})
	if err != nil {
		t.Fatalf("Invalidate: %v", err)
	}
	if inv.Time != 200 || len(inv.Landmarks) != 1 || inv.Landmarks[0].Occurrence != 1 {
		t.Fatalf("invalidation result = %+v", inv)
	}
	// 第 2 次出现：t=300 观测 → (3,2)，t=400 观测 → (4,2)，均值 (3.5,2) 计数 2。
	if _, err := m.ImportSegment(Segment{ID: "s2", Frames: []Frame{
		{Time: 300, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
		{Time: 400, DX: 1, MoveVariance: 0.1, Observations: []Observation{{ID: "D", X: 0, Y: 0}}},
	}}); err != nil {
		t.Fatal(err)
	}

	// 整体平移 +10：两次出现分别重放为 (11.5,2) 与 (13.5,2)，计数不变。
	rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 11, Y: 2, Heading: 0, Variance: 1}})
	if err != nil {
		t.Fatalf("Correct: %v", err)
	}
	if len(rec.Poses) != 4 || len(rec.Landmarks) != 2 {
		t.Fatalf("record should cover 4 poses and 2 occurrences: %+v", rec)
	}
	if rec.Landmarks[0].Occurrence != 1 || rec.Landmarks[1].Occurrence != 2 ||
		rec.Landmarks[0].ID != "D" || rec.Landmarks[1].ID != "D" {
		t.Fatalf("occurrence order = %+v", rec.Landmarks)
	}
	want := snapshotRecord(rec)

	// 调用方改写两次出现的编号与各次前后值。
	scrambleRecord(&rec)

	// 再次查询仍取得原始记录（出现编号 1、2 与真实前后值）。
	recs, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, recs, want)

	// 地图中两次出现的位置、计数与失效信息都不受影响。
	h, err := m.LandmarkAppearances("D")
	if err != nil {
		t.Fatal(err)
	}
	if len(h.Appearances) != 2 {
		t.Fatalf("appearances = %+v", h.Appearances)
	}
	ap1 := h.Appearances[0]
	if ap1.Number != 1 || ap1.Active || ap1.Landmark.Count != 2 {
		t.Fatalf("appearance 1 = %+v", ap1)
	}
	approxEq(t, "occ1 x", ap1.Landmark.X, 11.5)
	approxEq(t, "occ1 y", ap1.Landmark.Y, 2)
	if ap1.InvalidTime != 200 || ap1.InvalidReason != "stale" || ap1.InvalidOpID != "inv1" {
		t.Fatalf("appearance 1 invalidation info = %+v", ap1)
	}
	ap2 := h.Appearances[1]
	if ap2.Number != 2 || !ap2.Active || ap2.Landmark.Count != 2 {
		t.Fatalf("appearance 2 = %+v", ap2)
	}
	approxEq(t, "occ2 x", ap2.Landmark.X, 13.5)
	approxEq(t, "occ2 y", ap2.Landmark.Y, 2)

	// 区域查询仍只包含有效出现。
	lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
	if len(lms) != 1 || lms[0].ID != "D" {
		t.Fatalf("rect query = %v, want only active occurrence", lms)
	}
	approxEq(t, "active x", lms[0].X, 13.5)
	if lms[0].Count != 2 {
		t.Fatalf("active count = %d, want 2", lms[0].Count)
	}

	// 位姿同样保持真实校正结果。
	cur, _ := m.CurrentPose()
	if cur.Time != 400 || cur.X != 14 || cur.Y != 2 {
		t.Fatalf("current = %+v, want corrected (14,2)", cur)
	}
}

// Corrections 返回的列表同样是独立副本：改写其中记录、调换或替换
// 条目都不影响再次查询的内容与次序；先后取得的两份结果互不影响。
// 随后提交覆盖部分轨迹的新校正时，先前取得的结果保留获取时的内容，
// 保存的第一条记录仍说明第一次操作，新记录反映第二次操作实际发生
// 时的状态。
func TestCorrectionsListIsolation(t *testing.T) {
	m := newMap(t, baseConfig())
	if _, err := m.ImportSegment(corrSegment()); err != nil {
		t.Fatal(err)
	}
	c1 := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
	r1, err := m.Correct(c1)
	if err != nil {
		t.Fatal(err)
	}
	// 第二次校正把末帧移到 (11.5,20)：L1 两次观测 (11,20)/(11.5,20)
	// 距离 0.5 可接受，均值 (11.25,20)；M 移到 (11.5,21)。
	c2 := Correction{ID: "c2", Anchor: 200, Target: CorrectionTarget{X: 11.5, Y: 20, Heading: 0, Variance: 7}}
	r2, err := m.Correct(c2)
	if err != nil {
		t.Fatal(err)
	}
	// 测试侧快照作为对照，与被测实现的拷贝行为无关。
	s1, s2 := snapshotRecord(r1), snapshotRecord(r2)

	listA, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, listA, s1, s2)

	// 调用方改写列表中某条记录及其位姿、路标变化，并调换、替换条目。
	scrambleRecord(&listA[0])
	listA[0], listA[1] = listA[1], listA[0]
	listA[1] = CorrectionRecord{ID: "fake"}

	// 再次查询仍保留提交时的内容与先后次序。
	listB, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, listB, s1, s2)

	// 先后取得的两份结果互不干扰：改写 listB 不污染后续查询。
	scrambleRecord(&listB[0])
	listC, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, listC, s1, s2)

	// 提交第三次校正，覆盖第一次校正涉及的部分轨迹（末帧 t=200）：
	// 末帧 (11.5,20) → (11,20)，L1 均值 (11,20)，M → (11,21)。
	c3 := Correction{ID: "c3", Anchor: 200, Target: CorrectionTarget{X: 11, Y: 20, Heading: 0, Variance: 9}}
	r3, err := m.Correct(c3)
	if err != nil {
		t.Fatal(err)
	}
	if len(r3.Poses) != 1 || r3.Poses[0].Before.X != 11.5 || r3.Poses[0].After.X != 11 {
		t.Fatalf("third record = %+v, want before from c2 result", r3)
	}
	s3 := snapshotRecord(r3)

	// 先前取得的 listC 保留获取时的内容（仍只有两条记录）。
	checkRecords(t, listC, s1, s2)

	// 保存的第一条记录仍说明第一次操作的前后变化，新记录反映第三次
	// 操作实际发生时的变化。
	listD, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, listD, s1, s2, s3)
}

// 同一标识、同一原始请求再次提交：即使地图已接受后续校正，仍返回
// 首次记录而非最新轨迹，也不再增加记录；该返回结果同样可被调用方
// 独立改写而不污染之后查询或再次取得的首次结果。
func TestCorrectionDuplicateResultIsolation(t *testing.T) {
	m := newMap(t, baseConfig())
	if _, err := m.ImportSegment(corrSegment()); err != nil {
		t.Fatal(err)
	}
	c1 := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
	r1, err := m.Correct(c1)
	if err != nil {
		t.Fatal(err)
	}
	s1 := snapshotRecord(r1)
	// 地图接受后续校正，轨迹已不同于第一次校正后的状态。
	c2 := Correction{ID: "c2", Anchor: 200, Target: CorrectionTarget{X: 11.5, Y: 20, Heading: 0, Variance: 7}}
	if _, err := m.Correct(c2); err != nil {
		t.Fatal(err)
	}

	// 重复提交返回首次记录，不改为返回最新轨迹，也不增加记录。
	dup, err := m.Correct(c1)
	if err != nil {
		t.Fatalf("duplicate correction: %v", err)
	}
	if !recordsEqual(dup, s1) {
		t.Fatalf("duplicate returned %+v, want first record %+v", dup, s1)
	}
	recs, _ := m.Corrections()
	if len(recs) != 2 {
		t.Fatalf("duplicate added a record: %v", recs)
	}

	// 改写重复提交返回的结果，不污染之前取得的列表、之后查询与再次
	// 取得的首次结果。
	scrambleRecord(&dup)
	if !recordsEqual(recs[0], s1) {
		t.Fatalf("earlier query result polluted: %+v", recs[0])
	}
	recs, _ = m.Corrections()
	if len(recs) != 2 || !recordsEqual(recs[0], s1) {
		t.Fatalf("saved records polluted by scrambling duplicate result: %v", recs)
	}
	dup2, err := m.Correct(c1)
	if err != nil {
		t.Fatalf("second duplicate: %v", err)
	}
	if !recordsEqual(dup2, s1) {
		t.Fatalf("second duplicate returned %+v, want first record", dup2)
	}
	if recs, _ := m.Corrections(); len(recs) != 2 {
		t.Fatalf("second duplicate added a record: %v", recs)
	}
}

// 没有路标观测的合法校正同样保留位姿记录的隔离行为。
func TestCorrectionRecordIsolationNoLandmarks(t *testing.T) {
	m := newMap(t, baseConfig())
	// 无观测轨迹：p1 (2,2) v=0.6，p2 (3,2) v=0.7。
	if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
		{Time: 100, DX: 1, MoveVariance: 0.1},
		{Time: 200, DX: 1, MoveVariance: 0.1},
	}}); err != nil {
		t.Fatal(err)
	}
	rec, err := m.Correct(Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 5, Heading: 0, Variance: 1}})
	if err != nil {
		t.Fatal(err)
	}
	if len(rec.Poses) != 2 || len(rec.Landmarks) != 0 {
		t.Fatalf("record = %+v, want 2 pose changes and no landmark changes", rec)
	}
	want := snapshotRecord(rec)

	scrambleRecord(&rec)

	recs, err := m.Corrections()
	if err != nil {
		t.Fatal(err)
	}
	checkRecords(t, recs, want)

	cur, _ := m.CurrentPose()
	if cur.Time != 200 || cur.X != 11 || cur.Y != 5 || cur.Variance != 1.1 {
		t.Fatalf("current = %+v, want corrected (11,5) v=1.1", cur)
	}
	p, _ := m.PoseAt(100)
	if p.X != 10 || p.Y != 5 || p.Variance != 1 {
		t.Fatalf("pose at 100 = %+v, want corrected anchor", p)
	}
}

// Package posemap 是本地定位与地图的本地基线，提供可由本地程序调用的
// 二维轨迹与路标功能：创建地图、按段导入有序帧、查询历史位姿与矩形区域
// 内的路标，并把全部数据持久化到本地文件，关闭后重新打开结果一致。
package posemap

import (
	"errors"
	"math"
	"strconv"
)

// Config 描述创建一份新地图时的初始状态与两个阈值。
//
// 位置单位为米，时间单位为整数毫秒，朝向单位为弧度。初始位置方差
// InitialVariance 必须非负；最大帧间隔 MaxInterval（毫秒）与路标合并
// 距离 MergeDistance（米）必须为正。
type Config struct {
	InitialTime     int64   // 初始时间（毫秒）
	InitialX        float64 // 初始位置 X（米，地图坐标）
	InitialY        float64 // 初始位置 Y（米，地图坐标）
	InitialHeading  float64 // 初始朝向（弧度）
	InitialVariance float64 // 初始位置方差（非负）
	MaxInterval     int64   // 相邻位姿允许的最大时间间隔（毫秒，必须为正）
	MergeDistance   float64 // 路标观测合并距离（米，必须为正）
}

// Observation 是一帧中对单个路标的一次观测，位置在机器人自身坐标下。
type Observation struct {
	ID string  // 路标标识，非空
	X  float64 // 自身坐标下的 X（米）
	Y  float64 // 自身坐标下的 Y（米）
}

// Frame 是一段有序轨迹中的一帧：时间、自身坐标下的平移、朝向增量、
// 非负运动方差以及零个或多个路标观测。
type Frame struct {
	Time         int64         // 帧时间（毫秒）
	DX           float64       // 自身坐标下平移 X（米）
	DY           float64       // 自身坐标下平移 Y（米）
	DHeading     float64       // 朝向增量（弧度）
	MoveVariance float64       // 运动方差（非负）
	Observations []Observation // 零个或多个路标观测，同帧按输入次序处理
}

// Segment 是一批带有非空段标识的有序帧。
type Segment struct {
	ID     string  // 段标识，非空
	Frames []Frame // 有序帧
}

// Pose 是一份二维位姿及其位置方差。
type Pose struct {
	Time     int64
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Landmark 是地图坐标下的一个路标及其被接受的观测次数。
type Landmark struct {
	ID    string
	X     float64
	Y     float64
	Count int
}

// Invalidation 是一次路标失效操作：非空操作标识、非空原因与一组非空、
// 不重复的路标标识。提交时这些路标的当前有效记录同时失效，失效时间取
// 提交时的当前位姿时间。
type Invalidation struct {
	ID        string   // 操作标识，非空
	Reason    string   // 失效原因，非空
	Landmarks []string // 路标标识，非空且不重复
}

// InvalidationResult 是一次成功失效操作的结果：失效时间（提交时的当前
// 位姿时间）以及每个被撤下路标的标识与其失效的出现编号。
type InvalidationResult struct {
	Time      int64
	Landmarks []InvalidatedLandmark
}

// InvalidatedLandmark 记录一个被撤下路标的标识与被失效记录的出现编号。
type InvalidatedLandmark struct {
	ID         string
	Occurrence int
}

// Appearance 是同一标识某一次出现的记录：出现编号（同一标识首次出现为
// 1，每次失效后再次出现递增）、位置、观测计数、是否仍为当前有效记录、
// 首次观测时间，以及失效时间与原因。仍有效（Active 为真）时失效时间与
// 原因没有意义；旧文件缺少逐帧来源时 HasFirstSeen 为假，首次观测时间
// 未知。
type Appearance struct {
	Number        int // 出现编号，从 1 开始
	Landmark      Landmark
	Active        bool  // 是否为当前有效记录
	FirstSeenTime int64 // 首次观测所在帧的时间
	HasFirstSeen  bool  // 旧文件缺少逐帧来源时为假，表示首次观测时间未知
	InvalidTime   int64 // 失效时间（提交失效时的当前位姿时间）
	InvalidReason string
	InvalidOpID   string
}

// LandmarkHistory 是同一标识按出现编号递增排列的全部出现记录。
type LandmarkHistory struct {
	ID          string
	Appearances []Appearance
}

// CorrectionTarget 是已确认回环提交的目标：某个已保存帧应有的位姿与
// 非负位置方差。位置单位为米，朝向单位为弧度。
type CorrectionTarget struct {
	X        float64
	Y        float64
	Heading  float64
	Variance float64
}

// Correction 是一次已确认回环校正请求：非空标识、必须命中已导入帧的
// 锚点时间，以及该帧应有的位姿与非负位置方差。
type Correction struct {
	ID     string           // 校正标识，非空
	Anchor int64            // 已保存帧的准确时间（毫秒）
	Target CorrectionTarget // 锚点帧应有的位姿与方差
}

// PoseChange 是一帧位姿的校正前后值。
type PoseChange struct {
	Before Pose
	After  Pose
}

// LandmarkChange 是一个路标某一次出现的校正前后值（观测次数不变）。
// Occurrence 给出受影响的出现编号；同一标识的不同出现分别记录。
type LandmarkChange struct {
	ID         string
	Occurrence int
	Before     Landmark
	After      Landmark
}

// CorrectionRecord 是一次成功校正按提交次序保留的记录。后续校正可
// 覆盖相同时间范围，但先前记录永不被改写。
type CorrectionRecord struct {
	ID        string           // 校正标识
	Anchor    int64            // 锚点帧时间
	Target    CorrectionTarget // 提交目标
	EndTime   int64            // 受影响末帧时间（提交时的末帧）
	Poses     []PoseChange     // 受影响位姿的校正前后值，按时间升序
	Landmarks []LandmarkChange // 受影响路标出现的校正前后值，按标识再按出现编号升序
}

// RejectError 表示一次段导入、路标失效或回环校正因语义不合法而被整体
// 拒绝。
//
// Kind 为可区分的拒绝原因（见 Reject* 常量）；当原因涉及具体帧时，
// Frame 给出从零开始的帧序号且 HasFrame 为真；路标冲突时 Landmark
// 给出涉及的路标标识；重复段内容冲突时 Landmark 给出冲突的段标识。
// 两种情况下 HasLandmark 均为真。校正类原因用 Time 给出提交的锚点
// 时间且 HasTime 为真；校正中路标冲突时 Time 改为给出冲突观测所在帧的
// 时间、Landmark 给出路标标识、Occurrence 给出冲突的出现编号（1 起），
// HasLandmark 与 HasOccurrence 均为真。校正中某条观测转换到地图坐标后
// 出现非有限数值时同样处理：Time 为该观测所在帧的实际时间、Landmark
// 与 Occurrence 指出路标标识及其所属的出现编号。失效操作中找不到路标
// 或路标当前已失效时，Landmark 给出路标标识。
type RejectError struct {
	Kind          string
	Frame         int
	HasFrame      bool
	Landmark      string
	HasLandmark   bool
	Time          int64
	HasTime       bool
	Occurrence    int
	HasOccurrence bool
}

func (e *RejectError) Error() string {
	switch e.Kind {
	case RejectEmptySegment:
		return "posemap: segment has no frames"
	case RejectEmptyID:
		if e.HasFrame {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has empty landmark id"
		}
		return "posemap: empty segment, correction or invalidation id"
	case RejectEmptyReason:
		return "posemap: invalidation reason is empty"
	case RejectEmptyLandmarkList:
		return "posemap: invalidation landmark list is empty"
	case RejectDuplicateLandmarkEntry:
		return "posemap: invalidation lists landmark " + e.Landmark + " more than once"
	case RejectLandmarkNotFound:
		return "posemap: landmark " + e.Landmark + " not found"
	case RejectLandmarkInactive:
		return "posemap: landmark " + e.Landmark + " has no active occurrence"
	case RejectInvalidationMismatch:
		return "posemap: invalidation id " + e.Landmark + " already saved with different content"
	case RejectNegativeVariance:
		if e.HasTime {
			return "posemap: correction target variance is negative"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has negative motion variance"
	case RejectNonFinite:
		if e.HasTime {
			if e.HasLandmark {
				if e.HasOccurrence {
					return "posemap: correction makes observation of landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
				}
				return "posemap: correction makes observation of landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10) + " non-finite"
			}
			return "posemap: correction target or corrected result has non-finite value"
		}
		if e.HasLandmark {
			return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite observation of landmark " + e.Landmark
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " has non-finite value"
	case RejectTimeOrder:
		if e.Frame == 0 {
			return "posemap: first frame must be later than initial time or previous segment end"
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " time is not strictly increasing"
	case RejectInterval:
		return "posemap: frame " + strconv.Itoa(e.Frame) + " exceeds the maximum time interval"
	case RejectLandmarkConflict:
		if e.HasTime {
			if e.HasOccurrence {
				return "posemap: correction conflicts landmark " + e.Landmark + " occurrence " + strconv.Itoa(e.Occurrence) + " at frame time " + strconv.FormatInt(e.Time, 10)
			}
			return "posemap: correction conflicts landmark " + e.Landmark + " at frame time " + strconv.FormatInt(e.Time, 10)
		}
		return "posemap: frame " + strconv.Itoa(e.Frame) + " observation of landmark " + e.Landmark + " is beyond merge distance"
	case RejectDuplicateMismatch:
		return "posemap: segment id " + e.Landmark + " already saved with different content"
	case RejectAnchorNotFound:
		return "posemap: anchor time " + strconv.FormatInt(e.Time, 10) + " does not match an imported frame"
	case RejectCorrectionMismatch:
		return "posemap: correction id " + e.Landmark + " already saved with different content"
	case RejectNoBasis:
		return "posemap: correction range from " + strconv.FormatInt(e.Time, 10) + " lacks per-frame observation sources"
	default:
		return "posemap: request rejected (" + e.Kind + ")"
	}
}

// 可区分的拒绝原因。
const (
	RejectEmptySegment           = "empty_segment"            // 空批次
	RejectEmptyID                = "empty_id"                 // 空段/路标/校正/失效标识
	RejectEmptyReason            = "empty_reason"             // 失效原因为空
	RejectEmptyLandmarkList      = "empty_landmark_list"      // 失效路标列表为空
	RejectDuplicateLandmarkEntry = "duplicate_landmark_entry" // 失效列表中路标重复
	RejectLandmarkNotFound       = "landmark_not_found"       // 失效的路标从未出现
	RejectLandmarkInactive       = "landmark_inactive"        // 失效的路标当前无有效记录
	RejectInvalidationMismatch   = "invalidation_mismatch"    // 同一失效标识对应不同内容
	RejectNegativeVariance       = "negative_variance"        // 负运动方差或负目标方差
	RejectNonFinite              = "non_finite"               // 非有限数值（NaN/Inf）
	RejectTimeOrder              = "time_order"               // 时间未严格递增或首帧不够晚
	RejectInterval               = "interval_exceeded"        // 相邻位姿间隔超过上限
	RejectLandmarkConflict       = "landmark_conflict"        // 同标识路标超出合并距离
	RejectDuplicateMismatch      = "duplicate_mismatch"       // 同一段标识对应不同内容
	RejectAnchorNotFound         = "anchor_not_found"         // 校正锚点未命中已导入帧
	RejectCorrectionMismatch     = "correction_mismatch"      // 同一校正标识对应不同内容
	RejectNoBasis                = "no_basis"                 // 旧地图缺少逐帧观测来源
)

// 哨兵错误，供 errors.Is 使用。
var (
	// ErrClosed 在已关闭的地图上操作时返回。
	ErrClosed = errors.New("posemap: map is closed")
	// ErrInvalidConfig 在创建地图的配置不合法时返回。
	ErrInvalidConfig = errors.New("posemap: invalid config")
	// ErrInvalidRect 在矩形查询的上下界颠倒时返回。
	ErrInvalidRect = errors.New("posemap: invalid rectangle")
	// ErrNotFound 在查询时间早于初始时间（无任何不晚于它的位姿）时返回。
	ErrNotFound = errors.New("posemap: pose not found")
	// ErrLandmarkNotFound 在按标识查询路标历次出现而该标识从未出现时返回。
	ErrLandmarkNotFound = errors.New("posemap: landmark not found")
	// ErrCorrupt 在数据文件损坏、截断或校验失败时返回。
	ErrCorrupt = errors.New("posemap: corrupt data file")
	// ErrUnsupportedVersion 在数据文件格式版本不受支持时返回。
	ErrUnsupportedVersion = errors.New("posemap: unsupported file format version")
)

// normalizeAngle 把任意角度归一到 [-π, π)。
func normalizeAngle(a float64) float64 {
	a = math.Mod(a+math.Pi, 2*math.Pi)
	if a < 0 {
		a += 2 * math.Pi
	}
	return a - math.Pi
}

// isFinite 判断数值既不是 NaN 也不是 Inf。
func isFinite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }

// mergeMean 把一个新样本 v 并入既有等权均值（已有 count 个样本），
// 返回 count+1 个样本的均值。与 (mean*count + v)/(count+1) 数学等价，
// 但按 mean + (v-mean)/(count+1) 计算：大数值坐标下 mean*count 会溢出
// 为无穷，而这里每一步都只是有限值之间的凸组合，结果保持有限且落在
// 参与平均的坐标范围内。调用方须保证 v 与 mean 均为有限值且二者之差
// 有限（被接受的观测与当前均值相距不超过有限的合并距离，自然满足）。
func mergeMean(mean, v float64, count int) float64 {
	return mean + (v-mean)/float64(count+1)
}

// localToMap 把机器人自身坐标下的点 (lx, ly) 按给定地图坐标位姿
// 转换到地图坐标：旋转 heading 后平移。
func localToMap(px, py, heading, lx, ly float64) (float64, float64) {
	c, s := math.Cos(heading), math.Sin(heading)
	return px + c*lx - s*ly, py + s*lx + c*ly
}

