	}
	if _, ok := lms["M"]; ok {
		t.Fatalf("M reappeared in rect query: %v", lms)
	}

	// 历次出现查询保留旧记录的失效时间与原因。
	h, err := m.LandmarkAppearances("L")
	if err != nil {
		t.Fatal(err)
	}
