	}
	if len(hm.Appearances) != 1 || hm.Appearances[0].Active ||
		hm.Appearances[0].InvalidTime != 300 || hm.Appearances[0].InvalidReason != "retired" {
		t.Fatalf("M appearances = %+v", hm.Appearances)
	}
}

